// Wizz Clip news template timelines. Loaded by index.html; each scene file calls one builder with plan values
// generated by render.mjs from news.json. Everything visible is a function of a paused GSAP timeline;
// no timers, no CSS animations. Scene timelines run in the scene's local time (0 = its host's data-start).
(function () {
  var EASE = "power3.out", CUT_IN = 0.16, CUT_OUT = 0.2, EXIT = 0.14;

  // extend a scene timeline to its host slot so the runtime never sees it end early
  function pad(tl, dur) { tl.to({}, { duration: dur }, 0); }

  // one beat: entrance, mid-beat line, exit (beat 1 is fully visible at local t=0: it is the hook frame)
  function beat(b) {
    var tl = gsap.timeline({ paused: true }), id = "#b" + b.i + "-";
    if (b.vid) tl.fromTo(id + "vid", { scale: 1 }, { scale: 1.06, duration: b.dur, ease: "none" }, 0);
    if (b.img) tl.fromTo(id + "pic", { scale: 1 }, { scale: 1.07, duration: b.dur, ease: "none" }, 0);
    if (b.i > 0) {
      var s = 0;
      if (b.img) { tl.fromTo(id + "img", { clipPath: "inset(100% 0% 0% 0%)" }, { clipPath: "inset(0% 0% 0% 0%)", duration: 0.4, ease: EASE }, s); s += 0.06; }
      if (b.big) { tl.fromTo(id + "big", { opacity: 0, y: 44 }, { opacity: 1, y: 0, duration: 0.35, ease: EASE }, s); s += 0.08; }
      tl.fromTo(id + "text", { clipPath: "inset(-8% 100% -12% -2%)", x: -36 }, { clipPath: "inset(-8% -4% -12% -2%)", x: 0, duration: 0.38, ease: EASE }, s);
    }
    // one small line arrives mid-beat so something new shows every ~3 s
    if (b.sub) tl.fromTo(id + "sub", { opacity: 0, y: 22 }, { opacity: 1, y: 0, duration: 0.3, ease: EASE }, b.subAt);
    // exit lands just before the scene's clip ends
    tl.fromTo(id + "zone", { opacity: 1, x: 0 }, { opacity: 0, x: -44, duration: EXIT, ease: "power2.in" }, b.dur - EXIT - 0.02);
    pad(tl, b.dur);
    return tl;
  }

  // persistent chrome (global time): progress, Volt cut line at every beat boundary, leaves for the cover
  function chrome(P) {
    var tl = gsap.timeline({ paused: true });
    tl.set("#cut", { scaleX: 0, transformOrigin: "0% 50%" }, 0);
    P.beats.forEach(function (b) {
      var end = b.start + b.dur;
      tl.fromTo("#pf-" + b.i, { scaleX: 0 }, { scaleX: 1, duration: b.dur, ease: "none" }, b.start);
      tl.fromTo("#cut", { scaleX: 0 }, { scaleX: 1, duration: CUT_IN - 0.04, ease: "power2.in", immediateRender: false }, end - CUT_IN);
      tl.set("#cut", { transformOrigin: "100% 50%" }, end - 0.04);
      tl.fromTo("#cut", { scaleX: 1 }, { scaleX: 0, duration: CUT_OUT, ease: "power3.out", immediateRender: false }, end - 0.04);
      tl.set("#cut", { transformOrigin: "0% 50%" }, end + CUT_OUT);
    });
    tl.to("#hdr, #chip, #prog, #src", { opacity: 0, duration: EXIT, ease: "power2.in" }, P.coverStart - EXIT - 0.02);
    pad(tl, P.total);
    return tl;
  }

  // cover card (local time): the last ~1 s, settled well before the end; this is the TikTok cover
  function cover(dur, vid) {
    var tl = gsap.timeline({ paused: true });
    if (vid) tl.fromTo("#cv-vid", { scale: 1 }, { scale: 1.06, duration: dur, ease: "none" }, 0);
    tl.fromTo("#cv-chip", { opacity: 0, y: 24 }, { opacity: 1, y: 0, duration: 0.28, ease: EASE }, 0.02);
    tl.fromTo("#cv-title", { clipPath: "inset(-8% 100% -12% -2%)", x: -44 }, { clipPath: "inset(-8% -4% -12% -2%)", x: 0, duration: 0.38, ease: EASE }, 0.08);
    tl.fromTo("#cv-brand", { opacity: 0, y: 24 }, { opacity: 1, y: 0, duration: 0.3, ease: EASE }, 0.2);
    pad(tl, dur);
    return tl;
  }

  window.NEWS = { beat: beat, chrome: chrome, cover: cover };
})();
